import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintStream;
import java.io.UnsupportedEncodingException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

public class Tool {

    private static final DateTimeFormatter TS_FORMAT =
            DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss").withResolverStyle(ResolverStyle.STRICT);

    private static final Pattern UUID_PATTERN = Pattern.compile(
            "[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}");
    private static final Pattern HEX_PATTERN = Pattern.compile(
            "\\b(?=[0-9a-fA-F]*[a-fA-F])[0-9a-fA-F]{6,}\\b");
    private static final Pattern DIGIT_PATTERN = Pattern.compile("[0-9]+");

    private static final List<String> LEVELS = List.of("DEBUG", "INFO", "WARN", "ERROR");

    private static PrintStream out;
    private static PrintStream err;

    public static void main(String[] args) {
        try {
            out = new PrintStream(System.out, true, "UTF-8");
            err = new PrintStream(System.err, true, "UTF-8");
        } catch (UnsupportedEncodingException e) {
            throw new RuntimeException(e);
        }

        String file = null;
        String since = null;
        String level = null;
        int top = 5;

        int i = 0;
        while (i < args.length) {
            String a = args[i];
            if (a.equals("--help")) {
                printUsage(out);
                out.flush();
                System.exit(0);
                return;
            } else if (a.equals("--since")) {
                if (i + 1 >= args.length) {
                    usageError("missing value for --since");
                    return;
                }
                since = args[i + 1];
                i += 2;
            } else if (a.equals("--level")) {
                if (i + 1 >= args.length) {
                    usageError("missing value for --level");
                    return;
                }
                level = args[i + 1];
                i += 2;
            } else if (a.equals("--top")) {
                if (i + 1 >= args.length) {
                    usageError("missing value for --top");
                    return;
                }
                String v = args[i + 1];
                try {
                    top = Integer.parseInt(v);
                } catch (NumberFormatException e) {
                    usageError("invalid value for --top: " + v);
                    return;
                }
                i += 2;
            } else if (a.startsWith("--")) {
                usageError("unknown flag: " + a);
                return;
            } else {
                if (file == null) {
                    file = a;
                } else {
                    usageError("unexpected argument: " + a);
                    return;
                }
                i += 1;
            }
        }

        if (since != null && !isValidTimestamp(since)) {
            err.print("error: invalid value for --since: " + since + "\n");
            err.flush();
            System.exit(2);
            return;
        }

        if (level != null && !LEVELS.contains(level)) {
            err.print("error: invalid value for --level: " + level + "\n");
            err.flush();
            System.exit(2);
            return;
        }

        InputStream in;
        if (file == null || file.equals("-")) {
            in = System.in;
        } else {
            if (!Files.isReadable(Paths.get(file))) {
                err.print("error: cannot read " + file + "\n");
                err.flush();
                System.exit(2);
                return;
            }
            try {
                in = new FileInputStream(file);
            } catch (IOException e) {
                err.print("error: cannot read " + file + "\n");
                err.flush();
                System.exit(2);
                return;
            }
        }

        long total = 0;
        long[] levelCounts = new long[4];
        String first = null;
        String last = null;

        Map<String, Group> groups = new LinkedHashMap<>();

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                int i1 = line.indexOf(' ');
                if (i1 < 0) {
                    continue;
                }
                int i2 = line.indexOf(' ', i1 + 1);
                if (i2 < 0) {
                    continue;
                }
                String ts = line.substring(0, i1);
                String lvl = line.substring(i1 + 1, i2);
                String message = line.substring(i2 + 1);

                if (!isValidTimestamp(ts)) {
                    continue;
                }
                if (!LEVELS.contains(lvl)) {
                    continue;
                }

                if (since != null && ts.compareTo(since) < 0) {
                    continue;
                }
                if (level != null && !lvl.equals(level)) {
                    continue;
                }

                total++;
                levelCounts[LEVELS.indexOf(lvl)]++;
                if (first == null) {
                    first = ts;
                }
                last = ts;

                if (lvl.equals("ERROR")) {
                    String normalized = normalize(message);
                    Group g = groups.get(normalized);
                    if (g == null) {
                        g = new Group(message);
                        groups.put(normalized, g);
                    }
                    g.count++;
                }
            }
        } catch (IOException e) {
            err.print("error: cannot read " + file + "\n");
            err.flush();
            System.exit(2);
            return;
        }

        List<Group> groupList = new ArrayList<>(groups.values());
        groupList.sort((a, b) -> {
            if (a.count != b.count) {
                return Long.compare(b.count, a.count);
            }
            return a.message.compareTo(b.message);
        });

        StringBuilder sb = new StringBuilder();
        sb.append("total: ").append(total).append("\n");
        sb.append("by level: DEBUG=").append(levelCounts[0])
                .append(" INFO=").append(levelCounts[1])
                .append(" WARN=").append(levelCounts[2])
                .append(" ERROR=").append(levelCounts[3])
                .append("\n");
        sb.append("first: ").append(first == null ? "n/a" : first).append("\n");
        sb.append("last: ").append(last == null ? "n/a" : last).append("\n");
        sb.append("top errors:\n");
        int limit = Math.min(top, groupList.size());
        for (int idx = 0; idx < limit; idx++) {
            Group g = groupList.get(idx);
            sb.append("  ").append(g.count).append(" ").append(g.message).append("\n");
        }

        out.print(sb.toString());
        out.flush();
        System.exit(0);
    }

    private static void usageError(String message) {
        err.print("error: " + message + "\n");
        err.flush();
        System.exit(2);
    }

    private static boolean isValidTimestamp(String s) {
        if (s.length() != 19) {
            return false;
        }
        try {
            LocalDateTime.parse(s, TS_FORMAT);
            return true;
        } catch (DateTimeParseException e) {
            return false;
        }
    }

    private static String normalize(String message) {
        String m = message;
        m = UUID_PATTERN.matcher(m).replaceAll("<uuid>");
        m = HEX_PATTERN.matcher(m).replaceAll("<hex>");
        m = DIGIT_PATTERN.matcher(m).replaceAll("<num>");
        return m;
    }

    private static void printUsage(PrintStream o) {
        o.print("Usage: logsum [FILE] [--since TIMESTAMP] [--level LEVEL] [--top N]\n");
        o.print("\n");
        o.print("Streaming summary of a log file (or stdin).\n");
        o.print("\n");
        o.print("Arguments:\n");
        o.print("  FILE            log file to read (omit or use - for stdin)\n");
        o.print("\n");
        o.print("Options:\n");
        o.print("  --since TIMESTAMP  only consider lines with TIMESTAMP >= this value\n");
        o.print("  --level LEVEL      only consider lines at exactly this level\n");
        o.print("  --top N            number of top error groups to print (default 5)\n");
        o.print("  --help             show this help message\n");
    }

    private static class Group {
        final String message;
        long count;

        Group(String message) {
            this.message = message;
            this.count = 0;
        }
    }
}
